class Solution {
    public boolean hasPathSum(TreeNode root, int targetSum) {
        if (root == null) {
            return false;
        }
        int rest = targetSum - root.val;                // 往下还要凑多少
        if (root.left == null && root.right == null) {  // 叶子：看是不是正好凑够
            return rest == 0;
        }
        return hasPathSum(root.left, rest) || hasPathSum(root.right, rest);
    }
}

