class Solution {
    private int[][] grid;
    private int m, n;

    // 从 (i, j) 出发能淹掉多少块陆地
    private int dfs(int i, int j) {
        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != 1) {    // 出界、是水、或者来过
            return 0;
        }
        grid[i][j] = 2;                                 // 标记来过
        return 1 + dfs(i - 1, j) + dfs(i + 1, j) + dfs(i, j - 1) + dfs(i, j + 1);
    }

    public int maxAreaOfIsland(int[][] grid) {
        this.grid = grid;
        m = grid.length;
        n = grid[0].length;
        int best = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                best = Math.max(best, dfs(i, j));
            }
        }
        return best;
    }
}

