class Solution {
    private List<List<Integer>> rooms;
    private boolean[] seen;

    private void dfs(int u) {
        seen[u] = true;                             // 进了房间 u
        for (int v : rooms.get(u)) {                // 用房间里的钥匙
            if (!seen[v]) {                         // 没进过的才进去
                dfs(v);
            }
        }
    }

    public boolean canVisitAllRooms(List<List<Integer>> rooms) {
        this.rooms = rooms;
        seen = new boolean[rooms.size()];
        dfs(0);
        for (boolean s : seen) {
            if (!s) {
                return false;
            }
        }
        return true;
    }
}

